import type { EcoAction, EcoActionDifficulty } from "../../data/actions";
import { formatManwon } from "../../lib/format";

export interface ActionItemProps {
  action: EcoAction;
  /** Optional 1-based rank badge, useful when rendered inside an ordered list. */
  rank?: number;
  className?: string;
}

const DIFFICULTY_LABEL: Record<EcoActionDifficulty, string> = {
  easy: "쉬움",
  medium: "보통",
  hard: "어려움",
};

const DIFFICULTY_TONE_VARS: Record<EcoActionDifficulty, { fg: string; bg: string }> = {
  easy: { fg: "--status-good", bg: "--status-good-soft" },
  medium: { fg: "--status-caution", bg: "--status-caution-soft" },
  hard: { fg: "--status-warn", bg: "--status-warn-soft" },
};

/** List row for a recommended eco action, with its category, difficulty, and estimated savings. */
export function ActionItem({ action, rank, className }: ActionItemProps) {
  const tone = DIFFICULTY_TONE_VARS[action.difficulty];

  return (
    <li
      className={[
        "flex gap-[var(--space-4)] rounded-[var(--radius-lg)] border border-[var(--border-subtle)] bg-[var(--surface-card)] p-[var(--pad-card)]",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {rank !== undefined ? (
        <span
          aria-hidden="true"
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[var(--surface-sunken)] text-[length:var(--text-caption-size)] font-bold text-[var(--text-muted)]"
        >
          {rank}
        </span>
      ) : null}
      <div className="flex-1">
        <div className="flex flex-wrap items-center gap-[var(--space-2)]">
          <span className="text-[length:var(--text-caption-size)] font-bold text-[var(--text-muted)]">
            {action.category}
          </span>
          <span
            className="rounded-[var(--radius-pill)] px-[var(--space-2)] py-0.5 text-[length:var(--text-caption-size)] font-bold"
            style={{ color: `var(${tone.fg})`, backgroundColor: `var(${tone.bg})` }}
          >
            난이도 {DIFFICULTY_LABEL[action.difficulty]}
          </span>
        </div>
        <h3 className="mt-[var(--space-2)] text-[length:var(--text-subhead-size)] font-bold text-[var(--text-strong)]">
          {action.title}
        </h3>
        <p className="mt-[var(--space-1)] text-[length:var(--text-body-size)] leading-[var(--text-body-lh)] text-[var(--text-body)]">
          {action.description}
        </p>
        <p className="mt-[var(--space-3)] text-[length:var(--text-label-size)] font-bold text-[var(--status-good)]">
          월 {formatManwon(action.monthlySavingsManwon)} 절감 예상
        </p>
      </div>
    </li>
  );
}
