import Link from "next/link";
import { AppBar, PageHeader, SiteFooter } from "@/src/components/layout";
import { Card, Icon, ButtonLink } from "@/src/components/ui";
import { EnergyGradeBadge } from "@/src/components/domain";
import { searchBuildings } from "@/src/data/buildings";
import { formatDistance, formatNumber } from "@/src/lib/format";
import { SearchBar } from "./_components/SearchBar";

export const metadata = {
  title: "건물 에너지 등급 검색",
};

const SUGGESTED_QUERIES = ["월드컵로 120", "마포구", "상암"];

function normalizeQuery(raw: string | string[] | undefined): string | undefined {
  const value = Array.isArray(raw) ? raw[0] : raw;
  const trimmed = value?.trim();
  return trimmed ? trimmed : undefined;
}

export default async function SearchPage(props: PageProps<"/search">) {
  const searchParams = await props.searchParams;
  const query = normalizeQuery(searchParams.q);
  const hasQuery = query !== undefined;
  const results = await searchBuildings(query);

  return (
    <div className="flex min-h-dvh flex-col bg-[var(--surface-page)]">
      <AppBar />

      <main className="flex-1">
        <PageHeader
          eyebrow="건물 검색"
          title="우리 건물 에너지 등급 검색"
          description="도로명 주소를 입력하면 에너지효율등급과 인근 건물 비교 결과를 확인할 수 있어요."
        />

        <div className="eco-container flex flex-col gap-[var(--space-8)] pb-[var(--space-20)]">
          <SearchBar defaultValue={query ?? ""} className="max-w-2xl" />

          {hasQuery ? (
            <p
              role="status"
              className="text-[length:var(--text-label-size)] font-medium text-[var(--text-muted)]"
            >
              <span className="font-bold text-[var(--text-strong)]">&lsquo;{query}&rsquo;</span> 검색 결과{" "}
              {formatNumber(results.length)}건
            </p>
          ) : null}

          {!hasQuery ? (
            <Card padding="lg" className="flex flex-col items-center gap-[var(--space-4)] py-[var(--space-16)] text-center">
              <span
                aria-hidden="true"
                className="flex h-14 w-14 items-center justify-center rounded-full bg-[var(--surface-brand-soft)] text-[var(--text-link)]"
              >
                <Icon name="search" size={28} />
              </span>
              <div className="flex flex-col gap-[var(--space-2)]">
                <h2 className="eco-heading">검색할 주소를 입력해 주세요</h2>
                <p className="mx-auto max-w-md text-[length:var(--text-body-size)] text-[var(--text-muted)]">
                  건물의 도로명 주소를 입력하면 에너지효율등급, 인근 건물 비교, 맞춤 절감 방법까지 확인할 수 있어요.
                </p>
              </div>
              <div className="flex flex-wrap items-center justify-center gap-[var(--space-2)]">
                <span className="text-[length:var(--text-caption-size)] font-bold text-[var(--text-muted)]">
                  인기 검색어
                </span>
                {SUGGESTED_QUERIES.map((suggestion) => (
                  <Link
                    key={suggestion}
                    href={`/search?q=${encodeURIComponent(suggestion)}`}
                    className="rounded-[var(--radius-pill)] border border-[var(--border-subtle)] bg-[var(--surface-card)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-caption-size)] font-medium text-[var(--text-body)] transition-colors duration-[var(--dur-fast)] hover:border-[var(--border-brand)] hover:text-[var(--text-link)]"
                  >
                    {suggestion}
                  </Link>
                ))}
              </div>
            </Card>
          ) : results.length === 0 ? (
            <Card padding="lg" className="flex flex-col items-center gap-[var(--space-4)] py-[var(--space-16)] text-center">
              <span
                aria-hidden="true"
                className="flex h-14 w-14 items-center justify-center rounded-full bg-[var(--status-warn-soft)] text-[var(--status-warn)]"
              >
                <Icon name="info" size={28} />
              </span>
              <div className="flex flex-col gap-[var(--space-2)]">
                <h2 className="eco-heading">&lsquo;{query}&rsquo;에 대한 검색 결과가 없어요</h2>
                <p className="mx-auto max-w-md text-[length:var(--text-body-size)] text-[var(--text-muted)]">
                  주소 철자를 다시 확인하거나 동/도로명까지만 입력해 검색해보세요.
                </p>
              </div>
              <div className="flex flex-wrap items-center justify-center gap-[var(--space-2)]">
                {SUGGESTED_QUERIES.map((suggestion) => (
                  <Link
                    key={suggestion}
                    href={`/search?q=${encodeURIComponent(suggestion)}`}
                    className="rounded-[var(--radius-pill)] border border-[var(--border-subtle)] bg-[var(--surface-card)] px-[var(--space-4)] py-[var(--space-2)] text-[length:var(--text-caption-size)] font-medium text-[var(--text-body)] transition-colors duration-[var(--dur-fast)] hover:border-[var(--border-brand)] hover:text-[var(--text-link)]"
                  >
                    {suggestion}
                  </Link>
                ))}
              </div>
              <ButtonLink href="/search" variant="ghost" size="sm">
                전체 검색으로 돌아가기
              </ButtonLink>
            </Card>
          ) : (
            <ul className="grid grid-cols-1 gap-[var(--gap-card)] sm:grid-cols-2">
              {results.map((building) => (
                <li key={building.id}>
                  <Link href={`/report/${building.id}`} className="group block h-full">
                    <Card
                      interactive
                      className="flex h-full flex-col gap-[var(--space-3)] group-focus-visible:outline-2"
                    >
                      <div className="flex items-start justify-between gap-[var(--space-3)]">
                        <div className="flex flex-col gap-[var(--space-1)]">
                          <h3 className="eco-subhead text-[var(--text-strong)]">{building.name}</h3>
                          <p className="text-[length:var(--text-caption-size)] text-[var(--text-muted)]">
                            {building.address}
                          </p>
                        </div>
                        <EnergyGradeBadge grade={building.grade} size="md" />
                      </div>
                      <div className="mt-auto flex items-center gap-[var(--space-2)] text-[length:var(--text-caption-size)] font-medium text-[var(--text-muted)]">
                        <Icon name="building" size={16} />
                        <span>
                          {building.distanceMeters === 0
                            ? "검색 주소와 일치"
                            : `검색 주소에서 약 ${formatDistance(building.distanceMeters)}`}
                        </span>
                      </div>
                    </Card>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
      </main>

      <SiteFooter />
    </div>
  );
}
