import type { GradeDistributionEntry } from "../../data/grades";
import { getGradeColorVars } from "./grade-tokens";

export interface GradeScaleProps {
  /** Full grade distribution, best to worst (see `getGradeDistribution` in `src/data/grades.ts`). */
  distribution: GradeDistributionEntry[];
  className?: string;
}

/**
 * Visualizes where a building's grade sits on the 10-tier scale, plus how
 * many buildings fall into each grade.
 */
export function GradeScale({ distribution, className }: GradeScaleProps) {
  const maxCount = Math.max(1, ...distribution.map((entry) => entry.count ?? 0));
  const currentIndex = distribution.findIndex((entry) => entry.isCurrentBuildingGrade);
  const currentLabel = currentIndex >= 0 ? distribution[currentIndex].label : undefined;

  return (
    <div className={["flex flex-col gap-[var(--space-6)]", className].filter(Boolean).join(" ")}>
      <div>
        <div
          role="img"
          aria-label={
            currentLabel ? `건물 에너지효율등급 척도, 현재 건물은 ${currentLabel}` : "건물 에너지효율등급 척도"
          }
          className="flex h-3 overflow-hidden rounded-[var(--radius-pill)]"
        >
          {distribution.map((entry) => {
            const { color } = getGradeColorVars(entry.grade);
            return (
              <span
                key={entry.grade}
                aria-hidden="true"
                className="flex-1"
                style={{ backgroundColor: `var(${color})` }}
              />
            );
          })}
        </div>

        {currentIndex >= 0 ? (
          <div className="relative mt-[var(--space-2)] h-8" aria-hidden="true">
            <div
              className="absolute flex -translate-x-1/2 flex-col items-center gap-[var(--space-1)]"
              style={{ left: `${((currentIndex + 0.5) / distribution.length) * 100}%` }}
            >
              <span className="h-2 w-0.5 bg-[var(--ink-700)]" />
              <span className="whitespace-nowrap text-[length:var(--text-caption-size)] font-bold text-[var(--text-strong)]">
                현재 건물
              </span>
            </div>
          </div>
        ) : null}

        <div className="mt-[var(--space-1)] flex justify-between text-[length:var(--text-caption-size)] text-[var(--text-muted)]">
          <span>1+++등급 (우수)</span>
          <span>7등급 (취약)</span>
        </div>
      </div>

      <ul className="flex flex-col gap-[var(--space-1)]">
        {distribution.map((entry) => {
          const { color } = getGradeColorVars(entry.grade);
          const widthPercent = entry.count == null ? 0 : Math.max(4, (entry.count / maxCount) * 100);

          return (
            <li
              key={entry.grade}
              className={[
                "flex items-center gap-[var(--space-3)] rounded-[var(--radius-sm)] px-[var(--space-2)] py-[var(--space-1)]",
                entry.isCurrentBuildingGrade ? "bg-[var(--surface-brand-soft)]" : "",
              ]
                .filter(Boolean)
                .join(" ")}
            >
              <span className="w-14 shrink-0 text-[length:var(--text-caption-size)] font-bold text-[var(--text-body)]">
                {entry.label}
              </span>
              <span className="h-2 flex-1 overflow-hidden rounded-[var(--radius-pill)] bg-[var(--surface-card)]">
                {entry.count == null ? (
                  <span
                    className="block h-full w-full rounded-[var(--radius-pill)]"
                    style={{ border: "2px dashed", borderColor: `var(${color})` }}
                  />
                ) : (
                  <span
                    className="block h-full rounded-[var(--radius-pill)]"
                    style={{ width: `${widthPercent}%`, backgroundColor: `var(${color})` }}
                  />
                )}
              </span>
              <span className="w-16 shrink-0 text-right text-[length:var(--text-caption-size)] tabular-nums text-[var(--text-muted)]">
                {entry.count == null ? "현재 건물" : `${entry.count.toLocaleString("ko-KR")}동`}
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
